module sfu_lane
  import sfu_tables::*;
(
  input  logic [1:0]  op,          // 0 exp2, 1 rcp, 2 log2, 3 sigmoid
  input  logic [31:0] x,
  output logic [31:0] y
);
  localparam logic [31:0] NEG_LOG2E = 32'hbfb8aa3b;   // -1.4426950408889634 as binary32
  localparam logic [31:0] ONE = 32'h3f800000;

  // ---------------------------------------------------------------- exp2 on an f32
  function automatic logic [31:0] f_exp2(input logic [31:0] v);
    logic s; logic [7:0] e; logic [23:0] m; logic signed [9:0] sh;
    logic signed [63:0] fix;          // signed fixed point, 24 fraction bits
    logic signed [39:0] ip;           // integer part
    logic [23:0] fr; logic [5:0] idx; logic [17:0] rem;
    logic [24:0] t0, t1; logic [24:0] mant; logic [42:0] interp; logic signed [11:0] ex;
    s = v[31]; e = v[30:23]; m = {(e != 0), v[22:0]};
    if (e == 8'hff) return v[22:0] != 0 ? 32'h7fc00000 : (s ? 32'h00000000 : 32'h7f800000);
    sh = $signed({2'b0, e}) - 10'sd127;               // v = m * 2^(sh-23)
    if (!s && sh >= 7) return 32'h7f800000;           // v >= 128
    if (s && sh >= 7) return 32'h00000000;            // v <= -128
    if (sh >= 0) fix = 64'(m) <<< (sh + 1);           // m has 23 fraction bits; want 24
    else if (sh >= -25) fix = 64'(m) >>> (-sh - 1);
    else fix = 0;
    if (s) fix = -fix;
    if (s && fix <= -(64'sd127 <<< 24)) return 32'h00000000;   // x <= -127 -> 0 (simulator rule)
    ip = fix >>> 24; fr = fix[23:0];
    idx = fr[23:18]; rem = fr[17:0];
    t0 = EXP2_T[idx]; t1 = EXP2_T[idx + 1];
    interp = (43'(t1) - 43'(t0)) * 43'(rem);
    mant = t0 + 25'(interp >> 18);                    // 2^fr * 2^23 in [2^23, 2^24)
    ex = 12'(ip) + 12'sd127;
    if (ex >= 255) return 32'h7f800000;
    if (ex <= 0) return {1'b0, 8'd0, 23'(mant >> (1 - ex))};
    return {1'b0, 8'(ex), mant[22:0]};
  endfunction

  // ---------------------------------------------------------------- reciprocal
  function automatic logic [31:0] f_rcp(input logic [31:0] v);
    logic s; logic [7:0] e; logic [22:0] f; logic [4:0] lz; logic [22:0] fn; logic signed [11:0] Ei, ex;
    logic [6:0] idx; logic [15:0] rem; logic [24:0] t0, t1; logic [40:0] interp; logic [24:0] r;
    s = v[31]; e = v[30:23]; f = v[22:0];
    if (e == 8'hff) return (f != 0) ? 32'h7fc00000 : {s, 31'd0};
    if (e == 0 && f == 0) return {s, 8'hff, 23'd0};
    if (e == 0) begin                                  // subnormal: normalise
      lz = 0;
      for (int i = 22; i >= 0; i--) if (f[i]) begin lz = 5'(22 - i); break; end
      fn = 23'(f << (lz + 1));
      Ei = -12'sd126 - 12'(lz) - 12'sd1;
    end else begin fn = f; Ei = 12'(e) - 12'sd127; end
    idx = fn[22:16]; rem = fn[15:0];
    t0 = RCP_T[idx]; t1 = RCP_T[idx + 1];
    interp = (41'(t0) - 41'(t1)) * 41'(rem);
    r = t0 - 25'(interp >> 16);                        // 1/(1.f) * 2^24, in (2^23, 2^24]
    if (r[24]) begin ex = -Ei + 12'sd127; r = 25'h1000000; end    // exactly 1.0 (f == 0)
    else ex = -Ei - 12'sd1 + 12'sd127;
    if (ex >= 255) return {s, 8'hff, 23'd0};
    if (ex <= 0) return {s, 8'd0, 23'(r[23:0] >> (1 - ex))};
    return {s, 8'(ex), r[22:0]};
  endfunction

  // ---------------------------------------------------------------- log2
  function automatic logic [31:0] f_log2(input logic [31:0] v);
    logic s; logic [7:0] e; logic [22:0] f; logic [4:0] lz; logic [22:0] fn; logic signed [11:0] Ei;
    logic [7:0] idx; logic [14:0] rem; logic [24:0] t0, t1; logic [39:0] interp; logic [24:0] L;
    logic signed [35:0] fix; logic [35:0] mag; logic rs; int lead; logic [63:0] norm; logic signed [11:0] ex;
    s = v[31]; e = v[30:23]; f = v[22:0];
    if (e == 8'hff && f != 0) return 32'h7fc00000;
    if (e == 0 && f == 0) return 32'hff800000;
    if (s) return 32'h7fc00000;
    if (e == 8'hff) return 32'h7f800000;
    if (e == 0) begin
      lz = 0;
      for (int i = 22; i >= 0; i--) if (f[i]) begin lz = 5'(22 - i); break; end
      fn = 23'(f << (lz + 1));
      Ei = -12'sd126 - 12'(lz) - 12'sd1;
    end else begin fn = f; Ei = 12'(e) - 12'sd127; end
    idx = fn[22:15]; rem = fn[14:0];
    t0 = LOG2_T[idx]; t1 = LOG2_T[idx + 1];
    interp = (40'(t1) - 40'(t0)) * 40'(rem);
    L = t0 + 25'(interp >> 15);                        // log2(1.f) * 2^24 in [0, 2^24)
    fix = (36'(Ei) <<< 24) + 36'(L);                    // signed, 24 fraction bits
    if (fix == 0) return 32'h00000000;
    rs = fix[35]; mag = rs ? 36'(-fix) : 36'(fix);
    lead = 0;
    for (int i = 35; i >= 0; i--) if (mag[i]) begin lead = i; break; end
    norm = 64'(mag) << (63 - lead);                    // leading one at bit 63
    ex = 12'(lead - 24) + 12'sd127;
    return {rs, 8'(ex), norm[62:40]};
  endfunction

  logic [31:0] t, u, w, sig;
  f32_mul u_m (.a(x), .b(NEG_LOG2E), .y(t));
  always_comb u = f_exp2(t);
  f32_add u_a (.a(ONE), .b(u), .sub(1'b0), .y(w));
  always_comb begin
    sig = f_rcp(w);
    case (op)
      2'd0: y = f_exp2(x);
      2'd1: y = f_rcp(x);
      2'd2: y = f_log2(x);
      default: y = sig;
    endcase
  end
endmodule
